"""Upload-only product UI for automatic shot-intelligence jobs."""
PAGE = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FairwayOS · Automatic shot analysis</title><style>
:root{color-scheme:dark;font-family:Arial,sans-serif;background:#101a15;color:#eef3e7}*{box-sizing:border-box}body{margin:0}main{max-width:1200px;padding:32px;margin:auto}.brand{letter-spacing:2px;color:#b5e2c1;font-size:16px;font-weight:bold;border-bottom:1px solid #334135;padding-bottom:24px}h1{font-size:clamp(29px,4vw,43px);font-weight:500;letter-spacing:-1px;margin:32px 0 10px}p{color:#b9c9b7;line-height:1.6}.upload{display:block;border:1px dashed #617454;border-radius:12px;padding:36px;text-align:center;background:#152219;margin:26px 0;cursor:pointer}.upload:hover,.upload:focus-within{border-color:#c8e5ba}.upload strong{font-size:20px;font-weight:500}.upload span{display:block;color:#acc2a2;font-size:14px;margin-top:10px}input{display:block;margin:20px auto 0;max-width:100%;font:inherit}button,a.button{font:inherit;font-size:14px;border:1px solid #53624c;border-radius:6px;padding:11px 16px;background:#17251c;color:#e9efdf;cursor:pointer;text-decoration:none}button:focus-visible,a:focus-visible{outline:3px solid #f0d087;outline-offset:4px}button:disabled{opacity:.5;cursor:default}progress{width:100%;accent-color:#bfdeb6;height:8px}.status{display:flex;justify-content:space-between;gap:15px;align-items:center;margin:16px 0}.video{background:#08110c;border:1px solid #3d4d37;border-radius:10px;overflow:hidden}video{width:100%;display:block;max-height:72vh}.actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:18px 0}.actions a{background:#bfdeb6;color:#172319}.hint{font-size:13px}.error{color:#ffd2ad}details{border-top:1px solid #334135;margin-top:28px;padding-top:20px;color:#b9c9b7}summary{cursor:pointer}.hidden,[hidden]{display:none!important}h2{font-size:18px;font-weight:500}@media(max-width:650px){main{padding:22px 16px}.upload{padding:26px 15px}}
</style><main><div class="brand">FAIRWAYOS</div><h1>Your clip. The complete shot view.</h1><p>Choose a golf video. FairwayOS follows the visible ball, clubhead, body and cup, then returns your annotated clip and video-motion analytics.</p><label class="upload" for="clip"><strong>Choose a video to get started</strong><span>Analysis starts automatically. No points to mark or settings to fill in.</span><input id="clip" type="file" accept="video/*" aria-label="Choose a golf video"></label><p class="hint">AI-assisted analysis · original audio · clips up to 3 minutes</p><section id="job" hidden><div class="status"><p id="status" role="status" aria-live="polite">Preparing your clip…</p><button id="cancel">Cancel</button></div><progress id="progress" value="0" max="1" aria-label="Analysis progress"></progress><p id="error" class="error" role="alert"></p></section><section id="result" hidden><h2>Your annotated clip</h2><div class="video"><video id="video" controls playsinline preload="metadata"></video></div><div class="actions"><a id="download" class="button" download="fairwayos-shot.mp4">Download clip</a><a id="analytics-download" class="button" download="fairwayos-analytics.json">Download analytics</a><button id="overlay" aria-pressed="true">FairwayOS overlay</button><button id="original" aria-pressed="false">Original footage</button></div><p id="summary"></p><div id="metrics"></div><p class="hint">Mint marks the ball, blue marks the clubhead, subtle body anchors show the golfer, and gold marks the cup. Uncertain intervals stay blank.</p></section><details><summary>What the video can tell us</summary><p>FairwayOS follows current-frame body landmarks and clubhead evidence as well as visible balls. Clubheads need a hand-connected shaft and a separate visible head core; fast blur and occlusion can leave gaps. Cup targets need repeated rim evidence, with or without a flagstick. Trees, crowds and occlusion can still leave partial tracking.</p><p>Speed in mph, carry in yards, and an optimized aim point need reliable calibration or measured data. This version reports motion in source pixels per video-second and projected body angles. Broadcast slow motion can change these rates. Physical ball and clubhead mph, contact and swing tempo remain unverified.</p></details></main><script>
const token='__FAIRWAYOS_TOKEN__';const $=id=>document.getElementById(id);let job=null,timer=null,generation=0,choice='overlay';
async function jsonFetch(url,options){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw new Error(d.error||'Request failed');return d;}
function stop(){if(timer)clearTimeout(timer);timer=null;}
async function poll(g){if(g!==generation||!job)return;try{const d=await jsonFetch('/jobs/'+job);if(g!==generation)return;$('progress').value=d.progress||0;const terminal=['done','failed','cancelled'].includes(d.state);$('cancel').disabled=terminal;
 if(d.state==='done'){stop();$('status').textContent='Your clip is ready.';$('progress').value=1;const r=d.result;if(!r||!r.outputs||!r.outputs.video)throw new Error('The clip did not produce a video result.');$('result').hidden=false;$('video').src='/result-video?job='+job;$('download').href='/result-video?job='+job;$('analytics-download').href='/result-analytics?job='+job;choice='overlay';$('overlay').setAttribute('aria-pressed','true');$('original').setAttribute('aria-pressed','false');const layers=['ball','clubhead','body','cup'];$('summary').textContent=layers.map(name=>name[0].toUpperCase()+name.slice(1)+': '+(r.layers[name]?.frames_with_observation||0)+' observed frames').join(' · ')+'. Coverage is partial; unresolved intervals stay blank.';const m=r.analytics?.motion||{};const parts=[];for(const [key,label] of [['ball_ground_residual','Ball ground motion'],['clubhead_image','Clubhead image motion'],['hands_body_relative','Hand motion relative to hips']]){const x=m[key];if(x?.samples>=5)parts.push(label+': median '+Math.round(x.median)+' px/video-second ('+x.samples+' consecutive samples)');}if(parts.length)$('summary').textContent+=' '+parts.join('; ')+'. Physical mph unverified.';$('metrics').replaceChildren();const views=(r.analytics?.segments||[]).filter(s=>Object.keys(s.body_geometry||{}).length).sort((a,b)=>(b.motion.hands_body_relative?.samples||0)-(a.motion.hands_body_relative?.samples||0)).slice(0,4);views.forEach((s,i)=>{const values=[];for(const [key,label] of [['clubhead_image','Club image motion'],['hands_body_relative','Hands relative to hips']]){const split=key==='clubhead_image'?Object.values(s.club_motion_by_search_resolution||{}).map(v=>v[key]).sort((a,b)=>(b?.samples||0)-(a?.samples||0)):[];const m=split.length?split[0]:s.motion[key];if(m?.samples>=5)values.push(label+': '+Math.round(m.median)+' px/video-second');}const a=s.body_geometry.torso_axis_2d_degrees;if(a?.samples>=5)values.push('Projected torso axis: '+Math.round(a.median)+'°');if(values.length){const p=document.createElement('p');p.className='hint';p.textContent='Observed view '+(i+1)+' · '+values.join(' · ');$('metrics').append(p);}});
 }else if(d.state==='failed'){$('status').textContent='Analysis could not finish.';$('error').textContent=d.error||'Please try a different clip.';stop();}else if(d.state==='cancelled'){$('status').textContent='Analysis cancelled.';stop();}else{$('status').textContent=d.progress<.5?'Following the ball, clubhead, body and cup…':'Rendering and verifying your clip…';timer=setTimeout(()=>poll(g),1000);}
 }catch(e){if(g!==generation)return;$('error').textContent=e.message;stop();$('cancel').disabled=false;}}
$('clip').onchange=async()=>{const f=$('clip').files[0];if(!f)return;$('clip').value='';const oldJob=job;stop();const g=++generation;job=null;$('job').hidden=false;$('result').hidden=true;$('error').textContent='';$('status').textContent='Uploading '+f.name+'…';$('progress').value=0;$('cancel').disabled=true;$('clip').disabled=true;try{if(oldJob)await fetch('/jobs/'+oldJob+'/cancel',{method:'POST',headers:{'X-FairwayOS-Token':token}});const form=new FormData();form.append('video',f);form.append('analysis','shot_intelligence');const d=await jsonFetch('/jobs',{method:'POST',headers:{'X-FairwayOS-Token':token},body:form});if(g!==generation)return;job=d.id;$('cancel').disabled=false;poll(g);}catch(e){$('status').textContent='Could not start analysis.';$('error').textContent=e.message;}finally{$('clip').disabled=false;}};
$('cancel').onclick=async()=>{if(!job)return;try{await jsonFetch('/jobs/'+job+'/cancel',{method:'POST',headers:{'X-FairwayOS-Token':token}});poll(generation);}catch(e){$('error').textContent=e.message;}};
function select(id){if(!job||choice===id)return;const v=$('video'),t=v.currentTime,playing=!v.paused;choice=id;$('overlay').setAttribute('aria-pressed',id==='overlay');$('original').setAttribute('aria-pressed',id==='original');v.addEventListener('loadedmetadata',()=>{v.currentTime=Math.min(t,v.duration);if(playing)v.play().catch(()=>{});},{once:true});v.src=(id==='overlay'?'/result-video?job=':'/video?job=')+job;}
$('overlay').onclick=()=>select('overlay');$('original').onclick=()=>select('original');
$('video').addEventListener('error',()=>{$('error').textContent='Playback could not load. Use Download clip to open the local video.';});
</script></html>'''
